"""Add independent journals while preserving the original static page URLs."""
from pathlib import Path
import html, json

ROOT = Path(__file__).parent
SITE = ROOT / 'site'

def build(page, intro, rows, old_cards):
    projects = json.loads((ROOT/'content/projects.json').read_text(encoding='utf-8'))
    third = '''<a class="project football xbox" href="ncaa-football-07.html"><div class="yard-lines" aria-hidden="true"></div><div class="project-copy"><span class="status muted">● Recompilation research</span><p class="eyebrow">03 / FOOTBALL · ORIGINAL XBOX → WINDOWS</p><h3>NCAA Football 07<br>Recomp</h3><p>A childhood favorite, a new platform, and a long-term vision for Missouri high school football on PC.</p><span class="text-link">Explore the project ↗</span></div></a>'''
    expanded = old_cards().replace('<h3>College Baseball<br>Legacy</h3>', '<h3>MLB The Show 16<br>Recomp</h3><p class="project-subtitle">College Baseball Legacy · PS3 → Windows</p>').replace('<h3>Missouri High<br>School Football</h3>', '<h3>Missouri High<br>School Football Mod</h3>').replace('</div></a></div>', '</div></a>'+third+'</div>')
    for filename in ['index.html', 'projects.html']:
        path=SITE/filename
        path.write_text(path.read_text(encoding='utf-8').replace(old_cards(), expanded), encoding='utf-8')

    def gateways():
        return '<div class="journal-grid">'+''.join(f'<a class="journal-card" href="{p["journal"]}"><p class="eyebrow">{html.escape(p["platform"])}</p><h3>{html.escape(p["name"])}</h3><p>{html.escape(p["journal_summary"])}</p><span class="text-link">Open project journal →</span></a>' for p in projects)+'</div>'
    def announcements(body):
        return '<section class="project-announcements"><p class="eyebrow">PROJECT ANNOUNCEMENTS</p>'+body+'</section>'
    def append(filename, body):
        path=SITE/filename
        path.write_text(path.read_text(encoding='utf-8').replace('</main>',body+'</main>'),encoding='utf-8')

    path=SITE/'dev-logs.html'
    existing=path.read_text(encoding='utf-8')
    existing=existing.replace('Six updates from October 16 to November 3, 2026. The community story, with the engineering behind it.', 'Three projects. Three independent journals. Explore published milestones and follow each project’s journey.')
    existing=existing.replace('<section><div class="log-list">','<section>'+gateways()+'</section><section><div class="section-heading"><div><p class="eyebrow">COLLEGE BASEBALL LEGACY</p><h2>Published development logs</h2></div></div><div class="log-list">')
    path.write_text(existing,encoding='utf-8')

    page('college-baseball-legacy-dev-logs.html','College Baseball Legacy — Development Journal',intro('MLB THE SHOW 16 RECOMP / COLLEGE BASEBALL LEGACY','The baseball journal.','PS3 → Native Windows. Every published chapter of College Baseball Legacy, with its original article URL preserved.')+'<section><a class="text-link" href="college-baseball-legacy.html">← Project overview</a>'+rows(range(5,-1,-1))+'</section>', 'Dev Logs')
    append('college-baseball-legacy.html','<section><a class="button" href="college-baseball-legacy-dev-logs.html">Open the CBL journal →</a><p>MLB The Show 16 · PlayStation 3 → Native Windows · ps3recomp</p></section>'+announcements('<h2>Introducing our official logo.</h2><p>Our latest published announcement celebrates the College Baseball Legacy identity.</p><a class="text-link" href="dev-log-006.html">Read Dev Log 006 →</a>'))

    append('missouri-high-school-football.html','''<section class="split"><div><p class="eyebrow">NCAA FOOTBALL 14 / PLAYSTATION 3</p><h2>Research before expansion.</h2><p>The goal is to bring Missouri high school programs into NCAA Football 14, expand supported team counts, and implement Missouri high school playoff structures.</p><p>Early work includes establishing the workspace, collecting and verifying three EBOOT variants, and making initial structural comparisons. STEP-003 verification completed with nine passing tests, followed by STEP-004 provenance investigation.</p><p>Analysis compares the original executable with College Football Revamped and Forever14 to understand executable modifications and team expansion. Tools include Codex, VS Code, RPCS3, and executable and database analysis.</p></div><aside><p class="eyebrow">WHAT’S NEXT</p><h3>Build on the research.</h3><p>Team expansion and Missouri playoff implementation remain future development goals.</p><a class="button" href="missouri-high-school-football-dev-logs.html">Open the NCAA 14 journal →</a></aside></section>'''+announcements('<h2>Updates from the NCAA 14 project.</h2><p>Dedicated development articles and announcements will appear here as they are published.</p>'))
    page('missouri-high-school-football-dev-logs.html','Missouri High School Football Mod — Development Journal',intro('MISSOURI HIGH SCHOOL FOOTBALL MOD / NCAA FOOTBALL 14','Friday nights, documented.','An independent journal for the PS3 NCAA Football 14 mod. Numbering begins at #001 when the first article is published.')+'''<section class="empty"><p class="eyebrow">NO PUBLISHED ENTRIES YET</p><h2>The research is underway.</h2><p>Future articles will document executable analysis, team-expansion research, and the Missouri high school football vision.</p><a class="button" href="missouri-high-school-football.html">Back to the project →</a></section>''','Dev Logs')

    story='''<section class="split"><div><p class="eyebrow">THE ORIGIN STORY</p><h2>A childhood favorite.<br>A new possibility.</h2><p>NCAA Football 14 is my favorite video game of all time. But growing up, NCAA Football 07 held that spot for years.</p><p>Learning about original Xbox static recompilation and xboxrecomp opened up an exciting possibility: could one of my childhood favorites become a native Windows game?</p><p>That question sparked a new project under Orange Power Labs. First comes the challenge of bringing NCAA Football 07 to PC. The long-term dream is to turn that foundation into a Missouri high school football experience.</p></div><aside><p class="eyebrow">ORIGINAL XBOX → NATIVE WINDOWS</p><h3>Research in progress.</h3><p>Framework: xboxrecomp. Tools: Codex and VS Code, with Claude Code under consideration for primary development work.</p><p>Full executable linking, a successful game boot, and playable football have not been demonstrated. There is no public build or release date.</p><a class="button" href="ncaa-football-07-dev-logs.html">Open the Xbox journal →</a></aside></section>'''
    philosophy='''<section><p class="eyebrow">THE DEVELOPMENT APPROACH</p><h2>One verified step at a time.</h2><p>Development follows the pinned xboxrecomp repository’s README, Quick Start, getting-started documentation, and official pipeline instructions.</p><div class="pipeline" aria-label="Recompilation stages"><span>File analysis</span><span>Function identification</span><span>Function lifting</span><span>Object compilation</span><span>Executable linking</span><span>Runtime execution</span><span>Gameplay</span></div><p>These are separate stages, not interchangeable milestones. A research result or compiled object file does not establish that the game boots or is playable.</p></section>'''
    page('ncaa-football-07.html','NCAA Football 07 Recomp',intro('PROJECT 03 / RECOMPILATION RESEARCH','NCAA Football 07 Recomp','Bringing a childhood football favorite toward native Windows, with a Missouri high school football conversion as the long-term vision.')+story+philosophy+announcements('<h2>A new chapter for Orange Power Labs.</h2><p>NCAA Football 07 joins our lineup as a separate original Xbox recompilation effort. Its development journal will document the story as articles are published.</p><a class="text-link" href="ncaa-football-07-dev-logs.html">Explore the project journal →</a>'),'Projects')
    page('ncaa-football-07-dev-logs.html','NCAA Football 07 Recomp — Development Journal',intro('NCAA FOOTBALL 07 RECOMP / ORIGINAL XBOX','The Xbox recompilation journal.','An independent series beginning at #001. Follow the childhood-favorite origin story and the work toward native Windows.')+'''<section class="empty"><p class="eyebrow">NO PUBLISHED ENTRIES YET</p><h2>A story ready to begin.</h2><p>The opening articles are being prepared. This journal will cover the project’s origins, executable investigation, function research, and the path toward native compilation as each article is finalized.</p><a class="button" href="ncaa-football-07.html">Read the origin story →</a></section>''','Dev Logs')
    append('downloads.html','<section><p class="eyebrow">NCAA FOOTBALL 07 RECOMP</p><h2>Research, before releases.</h2><p>The original Xbox recompilation project has no public build or announced release date.</p><a class="text-link" href="ncaa-football-07.html">Follow the Xbox project →</a></section>')
    append('index.html','<section><div class="section-heading"><div><p class="eyebrow">THREE PROJECTS / ONE LAB</p><h2>Choose your development journal.</h2></div></div>'+gateways()+'</section>')
